// Secure application with environment variables
require('dotenv').config();

const express = require('express');
const helmet = require('helmet');
const app = express();

// Configuration from environment (12-factor app compliance)
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || '0.0.0.0';
const NODE_ENV = process.env.NODE_ENV || 'development';
const API_KEY = process.env.API_KEY;  // For simple API authentication

// Security middleware
app.use(helmet());

// Health check - no auth required for load balancers
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

// Simple API key middleware (for demonstration - use proper auth in production)
const authenticateApi = (req, res, next) => {
  if (NODE_ENV === 'development') {
    return next();  // Skip auth in development
  }
  const providedKey = req.headers['x-api-key'];
  if (!API_KEY) {
    return res.status(500).json({ error: 'Server configuration error' });
  }
  if (providedKey !== API_KEY) {
    return res.status(401).json({ error: 'Unauthorized' });
  }
  next();
};

// Users endpoint - protected in production
app.get('/users', authenticateApi, (req, res) => {
  // Test data - should ideally come from database
  const users = [
    { id: 1, name: process.env.USER_1_NAME || 'Alice', email: process.env.USER_1_EMAIL || 'alice@example.com' },
    { id: 2, name: process.env.USER_2_NAME || 'Bob', email: process.env.USER_2_EMAIL || 'bob@example.com' },
  ];
  res.json(users);
});

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err.stack);
  // Don't leak stack traces in production
  if (NODE_ENV === 'production') {
    return res.status(500).json({ error: 'Internal Server Error' });
  }
  res.status(500).json({ error: err.message, stack: err.stack });
});

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT} (${NODE_ENV})`);
});

module.exports = app;

